-- Автоматично згенеровано з офіційних карток Papa Carlo Plato.
-- 40 моделей, 422 унікальних фото для галереї.

begin;

delete from public.product_media
where product_slug in (
  select slug from public.products where brand = 'Papa Carlo' and collection = 'Plato'
);

on conflict (product_slug, kind, image_path) do update
set label = excluded.label, sort_order = excluded.sort_order, is_active = true;

commit;

select count(distinct product_slug) as моделей_з_галереєю, count(*) as усіх_фото
from public.product_media
where product_slug in (
  select slug from public.products where brand = 'Papa Carlo' and collection = 'Plato'
);
